package practice;
import java.util.*;
public class helloworld {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner input = new Scanner(System.in);
		int n = input.nextInt();
		int sum = 0;
		for(int i=1; i<n; i++){
		sum+=i;
		}
		System.out.println(sum);
		
	}

}
